        # 摘要规范化(serialize_metrics 拒绝非有限浮点)或结构校验会以
        # ValueError 拒绝, 不会泄漏其他异常类型。
        return float(value)
    if isinstance(value, list):
        normalized = None
        for index, element in enumerate(value):
            new_element = _normalize_checkpoint_numbers(element)
